<?php
/**
 * Direct project migration between two Upgrade Manager installations.
 * The source creates a private, time-limited migration share. The target
 * downloads it server-to-server, rewrites DB settings in staging, imports the
 * database and then atomically-ish replaces project files outside /upgrade/.
