class UMEProjectMigration {
    private $config;
    private $manager;
    private $upgradeDir;
    private $root;
    private $storage;
    private $migrationDir;
    private $secretDir;
    private $activeFile;

    public function __construct($config,$manager,$upgradeDir){
        $this->config=$config;
        $this->manager=$manager;
        $this->upgradeDir=rtrim(str_replace('\\','/',realpath($upgradeDir)?realpath($upgradeDir):$upgradeDir),'/');
        $this->root=rtrim(str_replace('\\','/',$manager->root()),'/');
        $this->storage=rtrim(str_replace('\\','/',$manager->storage()),'/');
        $this->migrationDir=$this->storage.'/migrations';
        $this->secretDir=$this->storage.'/migration-secrets';
        $this->activeFile=$this->storage.'/active-job.json';
        UMEUtil::ensureDir($this->migrationDir);@chmod($this->migrationDir,0700);
        UMEUtil::ensureDir($this->secretDir);@chmod($this->secretDir,0700);
        $this->pruneExpiredShares();$this->migrateLegacyJobSecrets();$this->pruneJobSecrets();$this->repairMigrationActivePointer();
    }

    private function jobFile($id){return $this->storage.'/jobs/'.$id.'.json';}
    private function logFile($id){return $this->storage.'/logs/'.$id.'.log';}
    private function cancelFile($id){return $this->storage.'/jobs/'.$id.'.cancel';}
    private function tempDir($id){return $this->storage.'/temp/'.$id;}
    private function secretFile($id){return $this->secretDir.'/'.$id.'.secret';}
    private function log($job,$message,$level){UMEUtil::appendLine($this->logFile($job['id']),'['.date('Y-m-d H:i:s').'] ['.$level.'] '.$message);}
    private function secretKeys($id){$master=isset($this->config['hmac_key'])?(string)$this->config['hmac_key']:'';if($master==='')throw new Exception('HMAC-ключ Upgrade Manager отсутствует; секреты миграции нельзя безопасно сохранить.');return array(hash('sha256','ume-migration-secret|enc|'.$id.'|'.$master,true),hash('sha256','ume-migration-secret|mac|'.$id.'|'.$master,true));}
    private function writeSecretBundle($id,$secrets){
        if(!$secrets){@unlink($this->secretFile($id));return;}if(!function_exists('openssl_encrypt')||!function_exists('openssl_decrypt'))throw new Exception('Для безопасного хранения реквизитов миграции требуется расширение OpenSSL.');
        $plain=json_encode($secrets,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($plain===false)throw new Exception('Не удалось подготовить секреты миграции.');list($encKey,$macKey)=$this->secretKeys($id);$cipherName='AES-256-CBC';$ivLen=openssl_cipher_iv_length($cipherName);$iv=function_exists('random_bytes')?random_bytes($ivLen):openssl_random_pseudo_bytes($ivLen);if($iv===false||strlen($iv)!==$ivLen)throw new Exception('Не удалось создать криптографический IV для миграции.');$flags=defined('OPENSSL_RAW_DATA')?OPENSSL_RAW_DATA:1;$cipher=openssl_encrypt($plain,$cipherName,$encKey,$flags,$iv);if($cipher===false)throw new Exception('Не удалось зашифровать реквизиты миграции.');$mac=hash_hmac('sha256',$iv.$cipher,$macKey,true);UMEUtil::jsonWriteAtomic($this->secretFile($id),array('format'=>'ume-migration-secret/1.0','cipher'=>$cipherName,'iv'=>base64_encode($iv),'data'=>base64_encode($cipher),'mac'=>base64_encode($mac)));@chmod($this->secretFile($id),0600);
    }
    private function readSecretBundle($id){
        $file=$this->secretFile($id);if(!is_file($file))return array();$box=UMEUtil::jsonRead($file,array());if(empty($box['iv'])||empty($box['data'])||empty($box['mac']))throw new Exception('Хранилище секретов миграции повреждено.');$iv=base64_decode($box['iv'],true);$cipher=base64_decode($box['data'],true);$mac=base64_decode($box['mac'],true);if($iv===false||$cipher===false||$mac===false)throw new Exception('Хранилище секретов миграции повреждено.');list($encKey,$macKey)=$this->secretKeys($id);$calc=hash_hmac('sha256',$iv.$cipher,$macKey,true);if(!hash_equals($calc,$mac))throw new Exception('Контроль целостности секретов миграции не пройден.');$flags=defined('OPENSSL_RAW_DATA')?OPENSSL_RAW_DATA:1;$plain=openssl_decrypt($cipher,isset($box['cipher'])?$box['cipher']:'AES-256-CBC',$encKey,$flags,$iv);if($plain===false)throw new Exception('Не удалось расшифровать реквизиты миграции.');$data=json_decode($plain,true);if(!is_array($data))throw new Exception('Расшифрованные реквизиты миграции повреждены.');return $data;
