    private function secretFields(){return array('db_password','source_url','migration_url','share_token','source_db_password');}
    private function extractJobSecrets(&$job){$out=array();if(empty($job['data'])||!is_array($job['data']))return $out;foreach($this->secretFields() as $key)if(array_key_exists($key,$job['data'])){$out[$key]=$job['data'][$key];unset($job['data'][$key]);}if(isset($job['data']['remote_info']['token'])){$out['remote_info_token']=$job['data']['remote_info']['token'];unset($job['data']['remote_info']['token']);}return $out;}
