    private function keepSecretsForJob($job){$status=isset($job['status'])?(string)$job['status']:'';if(in_array($status,array('running','stale','cancelling','rolling_back'),true))return true;if(isset($job['type'])&&$job['type']==='migration_export'&&$status==='completed'&&!empty($job['data']['expires_at'])){$ts=@strtotime((string)$job['data']['expires_at']);if($ts!==false&&$ts<=time())return false;if(!empty($job['data']['migration_id'])&&!is_dir($this->migrationDir.'/'.$job['data']['migration_id']))return false;return true;}return false;}
    private function writeJob($job){
        $job['updated_at']=UMEUtil::now();$persist=$job;$secrets=$this->extractJobSecrets($persist);$keep=$this->keepSecretsForJob($job);if($keep&&$secrets)$this->writeSecretBundle($job['id'],$secrets);UMEUtil::jsonWriteAtomic($this->jobFile($job['id']),$persist);if(!$keep)@unlink($this->secretFile($job['id']));
        if(in_array($job['status'],array('running','stale','cancelling','rolling_back'),true))UMEUtil::jsonWriteAtomic($this->activeFile,array('id'=>$job['id']));
        else { @unlink($this->cancelFile($job['id']));if(is_file($this->activeFile)){$a=UMEUtil::jsonRead($this->activeFile,array());if(isset($a['id'])&&$a['id']===$job['id'])@unlink($this->activeFile);} }
    }
    private function repairMigrationActivePointer(){
        if(is_file($this->activeFile)){$a=UMEUtil::jsonRead($this->activeFile,array());if(!empty($a['id'])){$j=UMEUtil::jsonRead($this->jobFile($a['id']),array());if($j&&in_array(isset($j['status'])?$j['status']:'',array('running','stale','cancelling','rolling_back'),true))return;}@unlink($this->activeFile);}
        $active=array();$files=glob($this->storage.'/jobs/mig-*.json');if(!is_array($files))$files=array();foreach($files as $file){$j=UMEUtil::jsonRead($file,array());if($j&&!empty($j['id'])&&in_array(isset($j['status'])?$j['status']:'',array('running','stale','cancelling','rolling_back'),true))$active[]=$j;}if($active){usort($active,function($a,$b){$at=isset($a['updated_at'])?@strtotime($a['updated_at']):0;$bt=isset($b['updated_at'])?@strtotime($b['updated_at']):0;if($at===$bt)return strcmp((string)$b['id'],(string)$a['id']);return $bt-$at;});UMEUtil::jsonWriteAtomic($this->activeFile,array('id'=>$active[0]['id']));}
    }
    // 3.6.3: the "changes started" flag (and the passed preflight) must be durable before the first
    // destructive operation. Otherwise a fatal PHP error inside the step followed by "Cancel" would
    // finish the job as cancelled and delete the safety copies without a rollback.
    private function persistChangesStarted(&$job){if(!empty($job['changes_started']))return;$job['changes_started']=true;$this->writeJob($job);$this->log($job,'Начаты изменения целевого проекта; признак сохранён до первой разрушительной операции.','INFO');}
    private function readJob($id){if(!UMEUtil::safeId($id))return null;$job=UMEUtil::jsonRead($this->jobFile($id),array());return $this->hydrateJobSecrets($job);}
    private function newJob($type,$data){
        $active=$this->manager->activeJob();if($active&&in_array($active['status'],array('running','stale','cancelling','rolling_back'),true))throw new Exception('Уже выполняется процесс: '.$active['id']);
        $id='mig-'.date('Ymd-His').'-'.substr(UMEUtil::randomHex(6),0,12);UMEUtil::ensureDir($this->tempDir($id));
        $job=array('id'=>$id,'type'=>$type,'status'=>'running','phase'=>'created','progress'=>0,'message'=>'Процесс создан','created_at'=>UMEUtil::now(),'updated_at'=>UMEUtil::now(),'cancel_requested'=>false,'changes_started'=>false,'data'=>$data);
