    public function publicJob($job){
        if(!$job)return null;$out=$job;
        if(isset($out['data'])&&is_array($out['data'])){
            foreach(array('db_password','source_url','migration_url','share_token','source_db_password') as $key)if(isset($out['data'][$key]))unset($out['data'][$key]);
            if(isset($out['data']['remote_info']['token']))unset($out['data']['remote_info']['token']);
            if(isset($job['type'])&&$job['type']==='migration_export')$out['data']['migration_link_available']=$this->exportLinkAvailable($job);
        }
        $active=in_array($job['status'],array('running','stale'),true);$out['cancel_allowed']=$active&&empty($job['cancel_requested'])&&strpos((string)$job['phase'],'rollback_')!==0;
        $out['log_tail']=UMEUtil::tail($this->logFile($job['id']),isset($this->config['limits']['log_tail_lines'])?(int)$this->config['limits']['log_tail_lines']:80);
        return $out;
    }
    private function exportLinkAvailable($job){
        if(!$job||!isset($job['type'])||$job['type']!=='migration_export'||!isset($job['status'])||$job['status']!=='completed'||empty($job['data'])||!is_array($job['data']))return false;
        if(empty($job['data']['migration_id'])||empty($job['data']['expires_at'])||empty($job['data']['migration_url']))return false;
        $expires=@strtotime((string)$job['data']['expires_at']);if($expires===false||$expires<=time())return false;
        if(!is_dir($this->migrationDir.'/'.$job['data']['migration_id'])||!is_file($this->secretFile($job['id'])))return false;
        return true;
    }
    public function exportLink($id){
        $job=$this->readJob($id);if(!$job||!isset($job['type'])||$job['type']!=='migration_export')throw new Exception('Процесс подготовки миграции не найден.');
        if(!$this->exportLinkAvailable($job))throw new Exception('Ссылка миграции уже использована, отозвана или истекла. Создайте новую ссылку.');
        $url=(string)$job['data']['migration_url'];$parts=@parse_url($url);if(!is_array($parts)||empty($parts['query']))throw new Exception('Сохранённая ссылка миграции повреждена. Создайте новую ссылку.');$query=array();parse_str($parts['query'],$query);$migrationId=isset($query['id'])?(string)$query['id']:'';$token=isset($query['token'])?(string)$query['token']:'';
        if($migrationId!==$job['data']['migration_id']||$token==='')throw new Exception('Сохранённая ссылка миграции повреждена. Создайте новую ссылку.');$this->validateShare($migrationId,$token);
        return array('job_id'=>$job['id'],'url'=>$url,'expires_at'=>$job['data']['expires_at']);
    }

    private function normalizeDomain($domain){
        $domain=strtolower(trim((string)$domain));$domain=preg_replace('#^https?://#i','',$domain);$domain=preg_replace('#/.*$#','',$domain);$domain=preg_replace('/:\d+$/','',$domain);$domain=rtrim($domain,'.');
        if($domain===''||strlen($domain)>253||!preg_match('/^[a-z0-9.-]+$/i',$domain)||strpos($domain,'.')===false)throw new Exception('Укажите корректный домен нового проекта без пути, например newsite.ru.');
        return $domain;
    }
    private function currentDomain(){return $this->normalizeDomain(UMEUtil::domain());}
    private function baseUrl(){
        $scheme=UMEUtil::isHttps()?'https':'http';$host=isset($_SERVER['HTTP_HOST'])?$_SERVER['HTTP_HOST']:UMEUtil::domain();$script=isset($_SERVER['SCRIPT_NAME'])?str_replace('\\','/',$_SERVER['SCRIPT_NAME']):'/upgrade/index.php';$dir=rtrim(dirname($script),'/\\');if($dir==='.'||$dir==='/')$dir='';return $scheme.'://'.$host.$dir;
    }
    private function migrationUrl($id,$token){return $this->baseUrl().'/migration.php?id='.rawurlencode($id).'&token='.rawurlencode($token);}
    private function storageRelativePath(){
        $root=$this->root.'/';$storage=rtrim($this->storage,'/');if(UMEUtil::startsWith($storage.'/', $root))return trim(substr($storage,strlen($root)),'/');return '';
    }
    private function excludedProjectPath($rel){
