        if($rel==='upgrade'||UMEUtil::startsWith($rel,'upgrade/'))return true;
        $storageRel=$this->storageRelativePath();if($storageRel!==''&&($rel===$storageRel||UMEUtil::startsWith($rel,$storageRel.'/')))return true;
        return false;
    }

    public function startExport($targetDomain){
