        $cms=UMECmsAdapter::detect($this->root);$db=$this->manager->databaseConfig(false);
        $data=array('target_domain'=>$target,'source_domain'=>$source,'cms'=>$cms,'db_detected'=>!empty($db['available']),'source_db'=>array('engine'=>isset($db['engine'])?$db['engine']:'unknown','host'=>isset($db['host'])?$db['host']:'','database'=>isset($db['database'])?$db['database']:'','user'=>isset($db['user'])?$db['user']:'','port'=>isset($db['port'])?(int)$db['port']:3306,'prefix'=>isset($db['prefix'])?$db['prefix']:'','source_files'=>isset($db['source_files'])&&is_array($db['source_files'])?$db['source_files']:array(),'config_location'=>isset($db['config_location'])?$db['config_location']:'root'),'scan_queue'=>array(''),'scan_current'=>null,'files_count'=>0,'bytes_total'=>0,'files_manifest_bytes'=>0,'file_index'=>0,'file_offset'=>0,'table_index'=>0,'row_offset'=>0,'rows_total'=>0,'rows_done'=>0,'crash_checkpoint_version'=>1);
        return $this->newJob('migration_export',$data);
