    public function startImport($sourceUrl,$dbHost,$dbPort,$dbName,$dbUser,$dbPassword){
        $sourceUrl=trim((string)$sourceUrl);if($sourceUrl===''||!preg_match('#^https://#i',$sourceUrl))throw new Exception('Укажите HTTPS-ссылку миграции со старого сайта.');
        $info=$this->fetchJson($sourceUrl);if(empty($info['ok'])||empty($info['migration'])||!is_array($info['migration']))throw new Exception(isset($info['error'])?$info['error']:'Ссылка миграции не вернула корректные данные.');
