        $manifest=$m['manifest'];$target=$this->normalizeDomain(isset($manifest['target_domain'])?$manifest['target_domain']:'');$current=$this->currentDomain();if($target!==$current)throw new Exception('Эта ссылка создана для домена '.$target.', а текущий Upgrade Manager открыт на '.$current.'.');
        if(!class_exists('ZipArchive'))throw new Exception('Для миграции требуется расширение ZipArchive.');if(!method_exists('ZipArchive','setCommentName')||!method_exists('ZipArchive','getCommentName'))throw new Exception('Для миграции 3.5.8 требуется ZipArchive с поддержкой комментариев записей ZIP.');if(!function_exists('openssl_encrypt')||!function_exists('openssl_decrypt'))throw new Exception('Для безопасного хранения пароля БД и migration token требуется расширение OpenSSL.');
        $dbIncluded=!empty($manifest['database_included']);$creds=array('host'=>trim((string)$dbHost),'port'=>(int)$dbPort,'database'=>trim((string)$dbName),'user'=>trim((string)$dbUser),'password'=>(string)$dbPassword);
        if($dbIncluded){if($creds['host']==='')$creds['host']='localhost';if($creds['port']<1||$creds['port']>65535)$creds['port']=3306;if($creds['database']===''||$creds['user']==='')throw new Exception('Для переноса БД укажите имя базы, пользователя и пароль.');$preDb=$this->dbConnect($creds,true);$requiredStmt=isset($manifest['database_max_statement_bytes'])?(int)$manifest['database_max_statement_bytes']:0;if($requiredStmt>0){$packet=$this->dbMaxAllowedPacket($preDb);if($packet>0&&$packet<$requiredStmt+65536){@$preDb->close();throw new Exception('На новой БД max_allowed_packet слишком мал для дампа: требуется не менее '.UMEUtil::formatBytes($requiredStmt+65536).', доступно '.UMEUtil::formatBytes($packet).'. Увеличьте max_allowed_packet до запуска миграции.');}}@$preDb->close();}
