        $data=array('source_url'=>$sourceUrl,'remote_info'=>$m,'manifest'=>$manifest,'db_host'=>$creds['host'],'db_port'=>$creds['port'],'db_name'=>$creds['database'],'db_user'=>$creds['user'],'db_password'=>$creds['password'],'download_site_offset'=>0,'download_db_offset'=>0,'extract_index'=>0,'staging_manifest_bytes'=>0,'safety_scan_queue'=>array(''),'safety_scan_current'=>null,'safety_files_count'=>0,'safety_manifest_bytes'=>0,'safety_file_index'=>0,'safety_file_offset'=>0,'safety_table_index'=>0,'safety_row_offset'=>0,'safety_rows_done'=>0,'safety_rows_total'=>0,'drop_index'=>0,'sql_offset'=>0,'replace_table_index'=>0,'replace_row_offset'=>0,'copy_index'=>0,'copy_offset'=>0,'installed_manifest_bytes'=>0,'clear_index'=>0,'clear_offset'=>0,'verify_index'=>0,'verify_offset'=>0,'verify_scan_queue'=>array(''),'verify_scan_current'=>null,'rollback_extract_index'=>0,'rollback_manifest_bytes'=>0,'rollback_sql_offset'=>0,'sql_delimiter'=>';','rollback_sql_delimiter'=>';','crash_checkpoint_version'=>1);
        return $this->newJob('migration_import',$data);
    }

    public function cancel($id){
        $job=$this->readJob($id);if(!$job||strpos((string)$job['type'],'migration_')!==0)throw new Exception('Процесс миграции не найден.');
        if(!in_array($job['status'],array('running','stale','cancelling','rolling_back'),true))return $this->publicJob($job);
        if(strpos((string)$job['phase'],'rollback_')===0)throw new Exception('Идёт безопасный возврат проекта. Этот этап нельзя прервать.');
        @file_put_contents($this->cancelFile($job['id']),UMEUtil::now(),LOCK_EX);$job['cancel_requested']=true;$job['status']='cancelling';$job['message']=!empty($job['changes_started'])?'Прерываем миграцию и возвращаем исходное состояние нового сайта.':'Прерываем миграцию до изменения сайта.';$this->writeJob($job);return $this->publicJob($job);
    }
    public function resume($id){$job=$this->readJob($id);if(!$job)throw new Exception('Процесс не найден.');if($job['status']==='stale'){$job['status']='running';$job['message']='Процесс продолжен пользователем';$this->writeJob($job);}return $this->publicJob($job);}

    public function step($id){
