            if($this->recoverCrashIntent($job)){$this->writeJob($job);@unlink($this->crashIntentFile($job));return $this->publicJob($job);}
            if(is_file($this->cancelFile($id)))$job['cancel_requested']=true;
            if(!empty($job['cancel_requested'])){
                if(empty($job['changes_started'])){$job['status']='cancelled';$job['phase']='cancelled';$job['progress']=100;$job['message']='Миграция прервана до изменения проекта';$this->cleanupTemp($job);$this->writeJob($job);return $this->publicJob($job);}
                if(strpos((string)$job['phase'],'rollback_')!==0){$job['status']='rolling_back';$job['phase']='rollback_files_scan';$job['message']='Прерывание принято. Возвращаем файлы и БД нового сайта.';$job['data']['rollback_scan_initialized']=false;$job['data']['rollback_manifest_bytes']=0;$job['data']['rollback_clear_index']=0;$job['data']['rollback_extract_index']=0;$job['data']['rollback_sql_offset']=0;$job['data']['rollback_sql_delimiter']=';';$this->log($job,'Начат rollback миграции после прерывания','WARN');$this->writeJob($job);return $this->publicJob($job);}
