    private function writeContentAtomic($file,$raw,$mode,$label){$dir=dirname($file);UMEUtil::ensureDir($dir);$tmp=$file.'.ume-tmp-'.UMEUtil::randomHex(4);$written=@file_put_contents($tmp,$raw,LOCK_EX);if($written===false||(int)$written!==strlen((string)$raw)){@unlink($tmp);throw new Exception('Не удалось полностью записать '.$label.'.');}if(!@chmod($tmp,(int)$mode&0777)){@unlink($tmp);throw new Exception('Не удалось выставить права для '.$label.'.');}if(!@rename($tmp,$file)){@unlink($tmp);throw new Exception('Не удалось атомарно заменить '.$label.'.');}}
