    private function rewriteKnownConfigPaths($root,$files,$oldDomain,$newDomain,$oldRoot,$newRoot){
        $changed=array();if(!is_array($files))return $changed;$oldDomain=trim((string)$oldDomain);$newDomain=trim((string)$newDomain);$oldRoot=rtrim(str_replace('\\','/',(string)$oldRoot),'/');$newRoot=rtrim(str_replace('\\','/',(string)$newRoot),'/');
