    }
    private function rewriteDatabaseConfig($root,$cmsId,$data){
        $host=$data['db_host'];$port=(int)$data['db_port'];$name=$data['db_name'];$user=$data['db_user'];$pass=$data['db_password'];$hostPort=$host.(($port&&$port!==3306)?':'.$port:'');$changed=array();$self=$this;
        $add=function($rel,$fn)use(&$changed,$root,$self){$n=$self->rewriteFile($root.'/'.$rel,$fn);if($n>0)$changed[]=$rel;};
        if($cmsId==='wordpress'){$add('wp-config.php',function(&$r)use($self,$hostPort,$name,$user,$pass){return $self->replaceDefine($r,'DB_HOST',$hostPort)+$self->replaceDefine($r,'DB_NAME',$name)+$self->replaceDefine($r,'DB_USER',$user)+$self->replaceDefine($r,'DB_PASSWORD',$pass);});}
        else if($cmsId==='opencart'){foreach(array('config.php','admin/config.php') as $rel)$add($rel,function(&$r)use($self,$host,$port,$name,$user,$pass){$n=$self->replaceDefine($r,'DB_HOSTNAME',$host)+$self->replaceDefine($r,'DB_DATABASE',$name)+$self->replaceDefine($r,'DB_USERNAME',$user)+$self->replaceDefine($r,'DB_PASSWORD',$pass);$n+=$self->replaceDefineNumber($r,'DB_PORT',$port);return $n;});}
        else if($cmsId==='joomla'){$add('configuration.php',function(&$r)use($self,$hostPort,$name,$user,$pass){return $self->replaceProp($r,'host',$hostPort)+$self->replaceProp($r,'db',$name)+$self->replaceProp($r,'user',$user)+$self->replaceProp($r,'password',$pass);});}
        else if($cmsId==='modx'){$add('core/config/config.inc.php',function(&$r)use($self,$hostPort,$name,$user,$pass){return $self->replaceVar($r,'database_server',$hostPort)+$self->replaceVar($r,'dbase',$name)+$self->replaceVar($r,'database_user',$user)+$self->replaceVar($r,'database_password',$pass);});}
        else if($cmsId==='prestashop'){
            $add('app/config/parameters.php',function(&$r)use($self,$host,$port,$name,$user,$pass){return $self->replaceArrayKey($r,'database_host',$host,1)+$self->replaceArrayNumber($r,'database_port',$port,1)+$self->replaceArrayKey($r,'database_name',$name,1)+$self->replaceArrayKey($r,'database_user',$user,1)+$self->replaceArrayKey($r,'database_password',$pass,1);});
            $add('config/settings.inc.php',function(&$r)use($self,$hostPort,$name,$user,$pass){return $self->replaceDefine($r,'_DB_SERVER_',$hostPort)+$self->replaceDefine($r,'_DB_NAME_',$name)+$self->replaceDefine($r,'_DB_USER_',$user)+$self->replaceDefine($r,'_DB_PASSWD_',$pass);});
        }
        else if($cmsId==='webasyst'){$add('wa-config/db.php',function(&$r)use($self,$host,$port,$name,$user,$pass){return $self->replaceArrayKey($r,'host',$host,1)+$self->replaceArrayNumber($r,'port',$port,1)+$self->replaceArrayKey($r,'database',$name,1)+$self->replaceArrayKey($r,'user',$user,1)+$self->replaceArrayKey($r,'password',$pass,1);});}
        else if($cmsId==='magento2'){$add('app/etc/env.php',function(&$r)use($self,$hostPort,$name,$user,$pass){return $self->replaceArrayKey($r,'host',$hostPort,2)+$self->replaceArrayKey($r,'dbname',$name,2)+$self->replaceArrayKey($r,'username',$user,2)+$self->replaceArrayKey($r,'password',$pass,2);});}
        else if($cmsId==='bitrix'){
            $add('bitrix/.settings.php',function(&$r)use($self,$hostPort,$name,$user,$pass){return $self->replaceArrayKey($r,'host',$hostPort,2)+$self->replaceArrayKey($r,'database',$name,2)+$self->replaceArrayKey($r,'login',$user,2)+$self->replaceArrayKey($r,'password',$pass,2);});
            $add('bitrix/php_interface/dbconn.php',function(&$r)use($self,$hostPort,$name,$user,$pass){return $self->replaceVar($r,'DBHost',$hostPort)+$self->replaceVar($r,'DBName',$name)+$self->replaceVar($r,'DBLogin',$user)+$self->replaceVar($r,'DBPassword',$pass);});
        }
