        return array_values(array_unique($changed));
    }

    /* ---------- Portable file metadata ---------- */
    private function projectMode($path,$fallback){$p=@fileperms($path);return $p===false?(int)$fallback:((int)$p&0777);}
    private function resolvePortableTargetRel($linkRel,$target){
        $target=str_replace('\\','/',(string)$target);if($target===''||substr($target,0,1)==='/'||preg_match('/^[A-Za-z]:\//',$target))throw new Exception('Символическая ссылка должна иметь переносимую относительную цель: '.$linkRel);$dir=dirname(str_replace('\\','/',$linkRel));$parts=$dir==='.'?array():explode('/',$dir);foreach(explode('/',$target) as $part){if($part===''||$part==='.')continue;if($part==='..'){if(!$parts)throw new Exception('Символическая ссылка выходит за пределы проекта: '.$linkRel.' -> '.$target);array_pop($parts);}else $parts[]=$part;}return implode('/',$parts);
    }
    private function relativeTarget($fromDirRel,$targetRel){$from=$fromDirRel===''||$fromDirRel==='.'?array():explode('/',trim($fromDirRel,'/'));$to=$targetRel===''?array():explode('/',trim($targetRel,'/'));$i=0;$max=min(count($from),count($to));while($i<$max&&$from[$i]===$to[$i])$i++;$out=array();for($j=$i;$j<count($from);$j++)$out[]='..';for($j=$i;$j<count($to);$j++)$out[]=$to[$j];return $out?implode('/',$out):'.';}
    private function collapseAbsolutePath($path){$path=str_replace('\\','/',(string)$path);$drive='';if(preg_match('/^([A-Za-z]:)(\/.*)$/',$path,$m)){$drive=strtoupper($m[1]);$path=$m[2];}if(substr($path,0,1)!=='/')return false;$parts=array();foreach(explode('/',$path) as $part){if($part===''||$part==='.')continue;if($part==='..'){if($parts)array_pop($parts);continue;}$parts[]=$part;}return $drive.'/'.implode('/',$parts);}
    private function portableSymlinkTarget($rel,$abs){
        $target=@readlink($abs);if($target===false)throw new Exception('Не удалось прочитать символическую ссылку: '.$rel);$target=str_replace('\\','/',$target);$root=$this->collapseAbsolutePath($this->root);if(substr($target,0,1)==='/'||preg_match('/^[A-Za-z]:\//',$target)){$normalized=$this->collapseAbsolutePath($target);if($normalized===false||$root===false||($normalized!==$root&&!UMEUtil::startsWith($normalized,$root.'/')))throw new Exception('Символическая ссылка '.$rel.' ведёт за пределы проекта: '.$target);$targetRel=ltrim(substr($normalized,strlen($root)),'/');return $this->relativeTarget(dirname($rel)==='.'?'':dirname($rel),$targetRel);}$targetRel=$this->resolvePortableTargetRel($rel,$target);return $this->relativeTarget(dirname($rel)==='.'?'':dirname($rel),$targetRel);
    }
    private function zipMetadata($zip,$name,$meta){if(!method_exists($zip,'setCommentName'))throw new Exception('ZipArchive на сервере не поддерживает метаданные файлов, необходимые для безопасного переноса symlink и прав.');$raw=json_encode($meta,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);if($raw===false||!$zip->setCommentName($name,'UME_META:'.$raw))throw new Exception('Не удалось записать метаданные ZIP для '.$name);if(method_exists($zip,'setExternalAttributesName')){$mode=isset($meta['mode'])?(int)$meta['mode']:0644;$type=isset($meta['type'])&&$meta['type']==='symlink'?0120000:0100000;@$zip->setExternalAttributesName($name,defined('ZipArchive::OPSYS_UNIX')?ZipArchive::OPSYS_UNIX:3,(($type|$mode)&0xFFFF)<<16);} }
    private function archiveProjectEntry($zip,$row,$base,$label){
        if(!is_array($row)||empty($row['path']))throw new Exception($label.' содержит повреждённую запись.');$rel=UMEUtil::normalizeRelativePath($row['path']);if($rel===false||$this->excludedProjectPath($rel))throw new Exception('Недопустимый путь в '.$label.': '.(isset($row['path'])?$row['path']:'?'));$type=isset($row['type'])?$row['type']:'file';$mode=isset($row['mode'])?((int)$row['mode']&0777):0644;
        if($type==='symlink'){$target=isset($row['target'])?(string)$row['target']:'';$this->resolvePortableTargetRel($rel,$target);if(!$zip->addFromString($rel,$target))throw new Exception('Не удалось добавить символическую ссылку в '.$label.': '.$rel);$this->zipMetadata($zip,$rel,array('type'=>'symlink','mode'=>$mode,'target'=>$target));return;}
