    private function extractZipEntry($zip,$index,$base,$format,$label,$rejectExisting=false,$allowRetryExisting=false){
        $st=$zip->statIndex($index);if(!is_array($st)||empty($st['name']))return null;$name=str_replace('\\','/',$st['name']);if(substr($name,-1)==='/')return null;$rel=UMEUtil::normalizeRelativePath($name);if($rel===false||$this->excludedProjectPath($rel)||$name!==$rel)throw new Exception('Недопустимый или неканонический путь в '.$label.': '.$name);$meta=$this->zipEntryMeta($zip,$index,$name,$format);$dest=rtrim($base,'/').'/'.$rel;UMEUtil::ensureDir(dirname($dest));if($rejectExisting&&(is_link($dest)||is_file($dest)||is_dir($dest))){$retryOk=false;if($allowRetryExisting&&!is_dir($dest)&&method_exists($zip,'locateName')){$first=$zip->locateName($name);$retryOk=$first!==false&&(int)$first===(int)$index;}if(!$retryOk)throw new Exception('Архив содержит дублирующийся или конфликтующий путь: '.$rel);}if(is_link($dest)||is_file($dest))@unlink($dest);
        if($meta['type']==='symlink'){$target=isset($meta['target'])?(string)$meta['target']:'';$content=$zip->getFromName($name);if($content===false||$content!==$target)throw new Exception('Повреждено содержимое symlink в '.$label.': '.$rel);$this->resolvePortableTargetRel($rel,$target);if(!function_exists('symlink')||!@symlink($target,$dest))throw new Exception('Не удалось восстановить символическую ссылку '.$rel.' во временном каталоге.');return array('path'=>$rel,'type'=>'symlink','mode'=>$meta['mode'],'target'=>$target);}
        $in=$zip->getStream($name);if(!$in)throw new Exception('Не удалось прочитать '.$rel.' из '.$label.'.');$out=@fopen($dest,'wb');if(!$out){fclose($in);throw new Exception('Не удалось записать '.$rel.' из '.$label.'.');}$copied=stream_copy_to_stream($in,$out);$closed=fclose($out);fclose($in);$expected=isset($st['size'])?(int)$st['size']:-1;if($copied===false||$closed===false||($expected>=0&&(int)$copied!==$expected)){@unlink($dest);throw new Exception('Не удалось полностью извлечь '.$rel.' из '.$label.'.');}if(!@chmod($dest,$meta['mode']))throw new Exception('Не удалось восстановить права '.$rel.' из '.$label.'.');return array('path'=>$rel,'type'=>'file','mode'=>$meta['mode']);
