    private function verifyInstalledEntry($entry){if(!is_array($entry)||empty($entry['path'])||empty($entry['type']))throw new Exception('Manifest установленных файлов повреждён.');$rel=UMEUtil::normalizeRelativePath($entry['path']);if($rel===false||$this->excludedProjectPath($rel))throw new Exception('Недопустимый путь в manifest установленных файлов.');$abs=$this->root.'/'.$rel;if($entry['type']==='symlink'){if(!is_link($abs))throw new Exception('После миграции отсутствует symlink: '.$rel);$target=@readlink($abs);if($target===false||$target!==(string)$entry['target'])throw new Exception('После миграции изменена цель symlink: '.$rel);$this->resolvePortableTargetRel($rel,$target);return true;}if(!is_file($abs)||is_link($abs))throw new Exception('После миграции отсутствует файл: '.$rel);$size=@filesize($abs);if(isset($entry['size'])&&$size!==false&&(int)$size!==(int)$entry['size'])throw new Exception('После миграции изменён размер файла: '.$rel);$sha=$this->hashFileRequired($abs,'установленный файл '.$rel);if(empty($entry['sha256'])||$sha!==strtolower((string)$entry['sha256']))throw new Exception('После миграции SHA-256 файла не совпадает: '.$rel);if(isset($entry['mode'])){$mode=$this->projectMode($abs,0644);if(($mode&0777)!==((int)$entry['mode']&0777))throw new Exception('После миграции права файла не совпадают: '.$rel);}return true;}
    private function removeProjectEntry($abs,$rel){if(is_link($abs)||is_file($abs)){if(!@unlink($abs))throw new Exception('Не удалось удалить файл или symlink перед миграцией: '.$rel);return;}if(file_exists($abs))throw new Exception('Ожидался файл или symlink, но найден другой тип: '.$rel);}

    /* ---------- File tree helpers ---------- */
    private function removeEmptyProjectDirs(){$dirs=array();$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($this->root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $f){if(!$f->isDir()||$f->isLink())continue;$rel=str_replace('\\','/',substr($f->getPathname(),strlen($this->root)+1));if($this->excludedProjectPath($rel))continue;$dirs[]=$f->getPathname();}foreach($dirs as $d)@rmdir($d);}
    private function clearKnownCaches(){foreach(array('wp-content/cache','bitrix/cache','bitrix/managed_cache','bitrix/stack_cache','wa-cache','storage/cache','system/storage/cache','var/cache','core/cache') as $rel){$path=$this->root.'/'.$rel;if(is_dir($path))UMEUtil::removeTree($path);}}
